"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, mq } from "./tokens.stylex";
import { rs } from "./rs";

export interface CrumbBarItem {
  label: React.ReactNode;
  href?: string;
}

export interface CrumbBarProps extends React.HTMLAttributes<HTMLElement> {
  trail: CrumbBarItem[];
  /** Pixels of scroll before the bar solidifies and the crumbs fade in. */
  threshold?: number;
  /** Root crumb, held in the TOC column from 900px. */
  root?: CrumbBarItem;
  /** Abbreviated root shown on phones in place of the full label. */
  rootShort?: React.ReactNode;
}

const styles = stylex.create({
  bar: {
    position: "fixed",
    top: 0,
    insetInlineStart: 0,
    insetInlineEnd: 0,
    zIndex: raster.zSticky,
    display: "flex",
    alignItems: "center",
    height: {
      default: "4.5rem",
      [mq.phone]: "4rem",
    },
    fontSize: {
      default: "0.8125rem",
      [mq.phone]: "0.75rem",
    },
    fontWeight: 500,
    letterSpacing: "-0.01em",
    lineHeight: 1.3,
    backgroundColor: "transparent",
    borderBottomWidth: raster.hairline,
    borderBottomStyle: "solid",
    borderBottomColor: "transparent",
    transition: raster.transition,
  },
  scrolled: {
    backgroundColor: raster.paper,
    borderBottomColor: raster.divider,
  },
  inner: {
    display: "flex",
    alignItems: "center",
    gap: {
      default: "1.25rem",
      [mq.at899]: "0.375rem",
    },
    width: "100%",
    minWidth: 0,
    paddingTop: 0,
    paddingBottom: 0,
    paddingInlineEnd: {
      default: "3.5rem",
      [mq.phone]: "3.125rem",
      [mq.mobileGrid]: "3.5rem",
    },
    paddingInlineStart: {
      default: "4.75rem",
      [mq.rail]: raster.pad,
      [mq.phone]: "3.875rem",
      [mq.mobileGrid]: "4.625rem",
    },
    marginInlineStart: {
      default: null,
      [mq.rail]: 204,
    },
  },
  crumbs: {
    listStyle: "none",
    padding: 0,
    margin: 0,
    minWidth: 0,
    overflow: "hidden",
    whiteSpace: "nowrap",
    opacity: 0,
    visibility: "hidden",
    pointerEvents: "none",
    transition: {
      default: `opacity ${raster.duration} ${raster.ease}, visibility 0s ${raster.ease} ${raster.duration}`,
      [mq.reduce]: "none",
    },
    fontSize: {
      default: "0.8125rem",
      [mq.phone]: raster.controlFs,
    },
    color: raster.ink,
    letterSpacing: "-0.01em",
    display: "flex",
    alignItems: {
      default: "baseline",
      [mq.phone]: "center",
    },
    flexWrap: {
      default: null,
      [mq.phone]: "wrap",
    },
    gap: {
      default: "0.5rem",
      [mq.phone]: "0.375rem",
    },
  },
  crumbsOn: {
    opacity: 1,
    visibility: "visible",
    pointerEvents: "auto",
    transition: {
      default: `opacity ${raster.duration} ${raster.ease}, visibility 0s`,
      [mq.reduce]: "none",
    },
  },
  item: {
    display: "inline-flex",
    alignItems: {
      default: "baseline",
      [mq.phone]: "center",
    },
    gap: {
      default: "0.5rem",
      [mq.phone]: "0.375rem",
    },
  },
  root: {
    flexShrink: 0,
    color: {
      default: raster.ink,
      ":link": raster.ink,
      ":visited": raster.ink,
    },
    textDecoration: "none",
    transition: `color ${raster.durationSnap} ${raster.ease}`,
    width: {
      default: null,
      [mq.at900]: 184,
    },
    fontWeight: {
      default: 500,
      [mq.at899]: 600,
    },
  },
  rootFull: {
    display: {
      default: null,
      [mq.phone]: "none",
    },
  },
  rootShort: {
    display: {
      default: "none",
      [mq.phone]: "inline",
    },
  },
  link: {
    transition: {
      default: raster.transition,
      [mq.reduce]: "none",
    },
    color: {
      default: raster.gray,
      ":link": raster.gray,
      ":visited": raster.gray,
      ":hover": raster.ink,
      ":active": raster.ink,
      ":focus-visible": raster.ink,
    },
    fontWeight: 400,
    textDecoration: {
      default: "none",
      ":hover": "underline",
    },
    textUnderlineOffset: 3,
    backgroundColor: "transparent",
    outlineWidth: {
      default: null,
      ":focus-visible": 2,
    },
    outlineStyle: {
      default: null,
      ":focus-visible": "solid",
    },
    outlineColor: {
      default: null,
      ":focus-visible": raster.ink,
    },
    outlineOffset: {
      default: null,
      ":focus-visible": 2,
    },
    display: {
      default: null,
      [mq.phone]: "inline-flex",
    },
    alignItems: {
      default: null,
      [mq.phone]: "center",
    },
    minHeight: {
      default: null,
      [mq.phone]: raster.hit,
    },
  },
  sep: {
    color: raster.gray,
  },
  here: {
    color: raster.ink,
    fontWeight: 500,
    overflow: "hidden",
    textOverflow: "ellipsis",
    display: {
      default: null,
      [mq.phone]: "inline-flex",
    },
    alignItems: {
      default: null,
      [mq.phone]: "center",
    },
    minHeight: {
      default: null,
      [mq.phone]: raster.hit,
    },
  },
});

/**
 * The fixed top bar of the house chrome. Transparent at rest; once the
 * page cover scrolls away it gains the paper background and its bottom
 * hairline, and the breadcrumbs fade in. While hidden the trail is
 * inert and invisible, so nothing focuses into an unseen link.
 */
export const CrumbBar = React.forwardRef<HTMLElement, CrumbBarProps>(function CrumbBar(
  { trail, threshold = 110, root, rootShort, className, style, ...props },
  ref,
) {
  const [scrolled, setScrolled] = React.useState(false);

  React.useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > threshold);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, [threshold]);

  const bar = rs(["rs-crumb-bar", scrolled && "rs-crumb-bar-scrolled", className], styles.bar, scrolled && styles.scrolled);
  const inner = rs(["rs-crumb-bar-inner"], styles.inner);
  const crumbs = rs(["rs-crumbs", "rs-crumb-crumbs", scrolled && "rs-crumb-crumbs-on"], styles.crumbs, scrolled && styles.crumbsOn);
  const item = rs(["rs-crumb-item"], styles.item);
  const rootSx = rs(["rs-crumb-root"], styles.root);
  const rootFull = rs(["rs-crumb-root-full"], styles.rootFull);
  const rootShortSx = rs(["rs-crumb-root-short"], styles.rootShort);
  const link = rs(["rs-crumbs-link", "rs-crumb-link"], styles.link);
  const sep = rs(["rs-crumbs-sep", "rs-crumb-sep"], styles.sep);
  const here = rs(["rs-crumbs-here", "rs-crumb-here"], styles.here);

  const rootLabel = rootShort ? (
    <>
      <span className={rootFull.className} style={rootFull.style}>
        {root?.label}
      </span>
      <span className={rootShortSx.className} style={rootShortSx.style}>
        {rootShort}
      </span>
    </>
  ) : (
    root?.label
  );

  return (
    <nav ref={ref} aria-label="Breadcrumb" {...props} className={bar.className} style={{ ...bar.style, ...style }}>
      <div className={inner.className} style={inner.style}>
        {root &&
          (root.href ? (
            <a className={rootSx.className} style={rootSx.style} href={root.href}>
              {rootLabel}
            </a>
          ) : (
            <span className={rootSx.className} style={rootSx.style}>
              {rootLabel}
            </span>
          ))}
        <ol className={crumbs.className} style={crumbs.style} inert={!scrolled}>
          {trail.map((crumb, index) => {
            const last = index === trail.length - 1;
            return (
              <li key={index} className={item.className} style={item.style}>
                {index > 0 && (
                  <span className={sep.className} style={sep.style} aria-hidden="true">
                    /
                  </span>
                )}
                {last ? (
                  <span className={here.className} style={here.style} aria-current="page">
                    {crumb.label}
                  </span>
                ) : crumb.href ? (
                  <a className={link.className} style={link.style} href={crumb.href}>
                    {crumb.label}
                  </a>
                ) : (
                  <span className={link.className} style={link.style}>
                    {crumb.label}
                  </span>
                )}
              </li>
            );
          })}
        </ol>
      </div>
    </nav>
  );
});

/* ── crumb-bar: generated from packages/react/src/components/crumb-bar.tsx ── */
.rs-crumb-bar{position:fixed;top:0;inset-inline-start:0;inset-inline-end:0;z-index:var(--z-sticky);display:flex;align-items:center;height:4.5rem;font-size:0.8125rem;font-weight:500;letter-spacing:-0.01em;line-height:1.3;background-color:transparent;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:transparent;transition:var(--transition)}
@media (max-width: 640px){.rs-crumb-bar{height:4rem;font-size:0.75rem}}
.rs-crumb-bar-scrolled{background-color:var(--bg);border-bottom-color:var(--divider)}
.rs-crumb-bar-inner{display:flex;align-items:center;gap:1.25rem;width:100%;min-width:0;padding-top:0;padding-bottom:0;padding-inline-end:3.5rem;padding-inline-start:4.75rem}
@media (max-width: 899px){.rs-crumb-bar-inner{gap:0.375rem}}
@media (max-width: 640px){.rs-crumb-bar-inner{padding-inline-end:3.125rem;padding-inline-start:3.875rem}}
@media (max-width: 480px){.rs-crumb-bar-inner{padding-inline-end:3.5rem;padding-inline-start:4.625rem}}
@media (min-width: 1024px){.rs-crumb-bar-inner{padding-inline-start:var(--pad);margin-inline-start:204px}}
.rs-crumbs.rs-crumb-crumbs{list-style:none;padding:0;margin:0;min-width:0;overflow:hidden;white-space:nowrap;opacity:0;visibility:hidden;pointer-events:none;transition:opacity var(--duration) var(--ease), visibility 0s var(--ease) var(--duration);font-size:0.8125rem;color:var(--text);letter-spacing:-0.01em;display:flex;align-items:baseline;gap:0.5rem}
@media (prefers-reduced-motion: reduce){.rs-crumbs.rs-crumb-crumbs{transition:none}}
@media (max-width: 640px){.rs-crumbs.rs-crumb-crumbs{font-size:var(--control-fs);align-items:center;flex-wrap:wrap;gap:0.375rem}}
.rs-crumb-crumbs-on{opacity:1;visibility:visible;pointer-events:auto;transition:opacity var(--duration) var(--ease), visibility 0s}
@media (prefers-reduced-motion: reduce){.rs-crumb-crumbs-on{transition:none}}
.rs-crumb-item{display:inline-flex;align-items:baseline;gap:0.5rem}
@media (max-width: 640px){.rs-crumb-item{align-items:center;gap:0.375rem}}
.rs-crumb-root{flex-shrink:0;color:var(--text);text-decoration:none;transition:color var(--duration-snap) var(--ease);font-weight:500}
.rs-crumb-root:link{color:var(--text)}
.rs-crumb-root:visited{color:var(--text)}
@media (min-width: 900px){.rs-crumb-root{width:184px}}
@media (max-width: 899px){.rs-crumb-root{font-weight:600}}
@media (max-width: 640px){.rs-crumb-root-full{display:none}}
.rs-crumb-root-short{display:none}
@media (max-width: 640px){.rs-crumb-root-short{display:inline}}
.rs-crumbs-link.rs-crumb-link{transition:var(--transition);color:var(--text-secondary);font-weight:400;text-decoration:none;text-underline-offset:3px;background-color:transparent}
.rs-crumbs-link.rs-crumb-link:link{color:var(--text-secondary)}
.rs-crumbs-link.rs-crumb-link:visited{color:var(--text-secondary)}
.rs-crumbs-link.rs-crumb-link:hover{color:var(--text);text-decoration:underline}
.rs-crumbs-link.rs-crumb-link:active{color:var(--text)}
.rs-crumbs-link.rs-crumb-link:focus-visible{color:var(--text);outline-width:2px;outline-style:solid;outline-color:var(--text);outline-offset:2px}
@media (prefers-reduced-motion: reduce){.rs-crumbs-link.rs-crumb-link{transition:none}}
@media (max-width: 640px){.rs-crumbs-link.rs-crumb-link{display:inline-flex;align-items:center;min-height:var(--hit)}}
.rs-crumbs-sep.rs-crumb-sep{color:var(--text-secondary)}
.rs-crumbs-here.rs-crumb-here{color:var(--text);font-weight:500;overflow:hidden;text-overflow:ellipsis}
@media (max-width: 640px){.rs-crumbs-here.rs-crumb-here{display:inline-flex;align-items:center;min-height:var(--hit)}}

